function validate([x, y, z]) {
  for (const [name, value] of [['x', x], ['y', y], ['z', z]]) {
    if (!Number.isInteger(value) || value < 1 || value > 50) return `${name} must be an integer from 1 to 50.`;
  }
  return null;
}

