function longestString(x, y, z) {
  // Try every allowed next piece from every state, checking the joined text directly.
  const pieces = ['AA', 'BB', 'AB'];
  const memo = new Map();
  const best = (left, tail) => {
    const key = left.join(',') + '|' + tail;
    if (memo.has(key)) return memo.get(key);
    let result = 0;
    for (let p = 0; p < 3; p++) {
      if (left[p] === 0) continue;
      const joined = tail + pieces[p];
      if (joined.includes('AAA') || joined.includes('BBB')) continue;
      const next = left.slice();
      next[p]--;
      result = Math.max(result, 2 + best(next, pieces[p]));
    }
    memo.set(key, result);
    return result;
  };
  return best([x, y, z], '');
}

